contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // amount: ether to send to c.play(); must be provided by caller
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe before state
        uint pot_before = c.pot();
        address bank_before = c.bank();
        uint bal_c_before = address(c).balance;

        // Call play and catch revert
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint pot_after = c.pot();
        uint bal_c_after = address(c).balance;

        // General rule:
        // - call reverts iff amount != TICKET_AMOUNT (10);
        // - if it reverted, pot unchanged;
        // - if it did not revert then amount == 10 and either:
        //     * pot increased by amount (no payout occurred), or
        //     * pot became 0 (payout occurred) and contract balance decreased accordingly.
        // We can't access TICKET_AMOUNT constant directly, so compare against 10.
        assert(
            // revert iff amount != 10
            (reverted && amount != 10) || (
                (!reverted) && amount == 10 && (
                    // If not reverted and amount==10 then either pot increased by amount...
                    (pot_after == pot_before + amount && bal_c_after == bal_c_before + amount) 
                    // ...or pot reset to 0 (payout happened). In that case c's balance may be less than before+amount
                    || (pot_after == 0)
                )
            )
        );
    }

    // Accept incoming refunds from c when it pays out
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We use amount as the Ether sent to c.play. Must be provided by the fuzzer.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // Observe pre-call values
        address bankBefore = c.bank();
        uint potBefore = c.pot();
        uint cBalanceBefore = address(c).balance;
        uint myBalanceBefore = address(this).balance;

        bool reverted;
        // call play with provided amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call values
        address bankAfter = c.bank();
        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;
        uint myBalanceAfter = address(this).balance;

        // General invariant: bank address never changes; Ether is conserved between c and this contract
        // and any transfer to bank equals FEE_AMOUNT when a payout occurred.
        // We cannot read FEE_AMOUNT, but we can assert that if pot was reset to 0 then c's balance decreased by potBefore
        // (minus any fee) and this contract's balance increased by potBefore - fee; combined with bank receiving the fee,
        // the sum of balances (c + this + implicit bank) is conserved. Since we cannot read bank's balance, we assert
        // conservation between c and this plus that bank address is unchanged and that when potAfter == 0 the c.balance <= cBalanceBefore.

        assert(
            bankBefore == bankAfter &&
            // If call reverted, no state change in c should have occurred (pot and c balance unchanged)
            (reverted ? (potAfter == potBefore && cBalanceAfter == cBalanceBefore && myBalanceAfter == myBalanceBefore)
             :
             // If not reverted, then either pot increased by amount (when not payout) or pot reset to 0 (when payout).
             // In both cases cBalanceAfter == cBalanceBefore + amount - ( (potBefore>0 && potAfter==0) ? potBefore : 0 )
             // which ensures Ether moved either into pot or was paid out (reducing c balance by previous pot on payout).
             (
               (
                 // case: no payout -> pot increases exactly by amount and c balance increases by amount
                 potAfter == potBefore + amount && cBalanceAfter == cBalanceBefore + amount
               ) ||
               (
                 // case: payout -> pot becomes 0 and c balance increased by amount then decreased by potBefore (net change: +amount - potBefore)
                 potAfter == 0 && cBalanceAfter == cBalanceBefore + amount - potBefore
               )
             )
            )
        );
    }

    // accept ETH refunds when c.transfer sends to this contract during tests
    receive() external payable {}
}

